package com.ashkan.hotel;

import java.io.IOException;
import java.math.*;
import java.nio.charset.StandardCharsets;
import java.nio.file.*;
import java.time.*;
import java.util.*;

/** Local channel manager for external booking imports, room-type allotments, rates and commissions. */
public final class ChannelManagerService {
    public enum BookingStatus { CONFIRMED, CANCELLED, CHECKED_IN, CHECKED_OUT }
    public record Channel(String id,String name,BigDecimal commissionPercent,boolean active) {
        public Channel { id=req(id).toUpperCase(Locale.ROOT);name=req(name);Objects.requireNonNull(commissionPercent);if(commissionPercent.signum()<0||commissionPercent.compareTo(new BigDecimal("100"))>0)throw new IllegalArgumentException("Commission must be between 0 and 100"); }
    }
    public record RoomType(String code,String name,int physicalRooms) {
        public RoomType { code=req(code).toUpperCase(Locale.ROOT);name=req(name);if(physicalRooms<1)throw new IllegalArgumentException("Room count must be positive"); }
    }
    public record Rate(String roomType,String channel,LocalDate from,LocalDate to,BigDecimal nightlyRate,int allotment) {
        public Rate { roomType=req(roomType).toUpperCase(Locale.ROOT);channel=req(channel).toUpperCase(Locale.ROOT);Objects.requireNonNull(from);Objects.requireNonNull(to);Objects.requireNonNull(nightlyRate);if(to.isBefore(from)||nightlyRate.signum()<=0||allotment<0)throw new IllegalArgumentException("Invalid rate period, price or allotment"); }
    }
    public record ExternalBooking(long id,String channel,String externalReference,String guestName,String roomType,LocalDate checkIn,LocalDate checkOut,int rooms,BigDecimal nightlyRate,BookingStatus status,LocalDateTime importedAt) {
        public ExternalBooking { channel=req(channel).toUpperCase(Locale.ROOT);externalReference=req(externalReference);guestName=req(guestName);roomType=req(roomType).toUpperCase(Locale.ROOT);Objects.requireNonNull(checkIn);Objects.requireNonNull(checkOut);Objects.requireNonNull(nightlyRate);Objects.requireNonNull(status);Objects.requireNonNull(importedAt);if(!checkOut.isAfter(checkIn)||rooms<1||nightlyRate.signum()<=0)throw new IllegalArgumentException("Invalid booking dates, room count or rate"); }
        public long nights(){return java.time.temporal.ChronoUnit.DAYS.between(checkIn,checkOut);} public BigDecimal gross(){return nightlyRate.multiply(BigDecimal.valueOf(nights()*rooms)).setScale(2,RoundingMode.HALF_UP);}
    }
    private final Path file;private final Clock clock;private final Map<String,Channel> channels=new TreeMap<>();private final Map<String,RoomType> roomTypes=new TreeMap<>();private final List<Rate> rates=new ArrayList<>();private final List<ExternalBooking> bookings=new ArrayList<>();private long nextId=1;
    public ChannelManagerService(){this(Path.of(System.getProperty("user.home"),".ashkan-hotelsphere","channels.tsv"),Clock.systemDefaultZone());}
    public ChannelManagerService(Path file,Clock clock){this.file=Objects.requireNonNull(file);this.clock=Objects.requireNonNull(clock);try{Files.createDirectories(file.toAbsolutePath().getParent());if(Files.exists(file))load();}catch(IOException e){throw new IllegalStateException("Cannot load channel manager",e);}}
    private static String req(String s){String x=s==null?"":s.strip();if(x.isEmpty())throw new IllegalArgumentException("Required value is missing");return x;}
    private static String enc(String s){return Base64.getEncoder().encodeToString(s.getBytes(StandardCharsets.UTF_8));}private static String dec(String s){return new String(Base64.getDecoder().decode(s),StandardCharsets.UTF_8);}
    public synchronized void saveChannel(Channel c)throws IOException{channels.put(c.id(),c);persist();}
    public synchronized void saveRoomType(RoomType r)throws IOException{roomTypes.put(r.code(),r);persist();}
    public synchronized void saveRate(Rate r)throws IOException{requireChannel(r.channel());requireRoom(r.roomType());rates.removeIf(x->x.roomType().equals(r.roomType())&&x.channel().equals(r.channel())&&!x.to().isBefore(r.from())&&!x.from().isAfter(r.to()));rates.add(r);persist();}
    public synchronized List<Channel> channels(){return List.copyOf(channels.values());}public synchronized List<RoomType> roomTypes(){return List.copyOf(roomTypes.values());}public synchronized List<Rate> rates(){return List.copyOf(rates);}public synchronized List<ExternalBooking> bookings(){return bookings.stream().sorted(Comparator.comparing(ExternalBooking::importedAt).reversed()).toList();}
    public synchronized int available(String roomType,String channel,LocalDate date){RoomType rt=requireRoom(roomType);Channel ch=requireChannel(channel);if(!ch.active())return 0;Rate rate=rateFor(rt.code(),ch.id(),date);if(rate==null)return 0;int sold=(int)bookings.stream().filter(b->b.roomType().equals(rt.code())&&b.status()!=BookingStatus.CANCELLED&&b.checkIn().isBefore(date.plusDays(1))&&b.checkOut().isAfter(date)).mapToInt(ExternalBooking::rooms).sum();int global=(int)bookings.stream().filter(b->b.roomType().equals(rt.code())&&b.status()!=BookingStatus.CANCELLED&&b.checkIn().isBefore(date.plusDays(1))&&b.checkOut().isAfter(date)).mapToInt(ExternalBooking::rooms).sum();return Math.max(0,Math.min(rate.allotment()-sold,rt.physicalRooms()-global));}
    public synchronized ExternalBooking importBooking(String channel,String reference,String guest,String roomType,LocalDate in,LocalDate out,int rooms,BigDecimal quotedRate)throws IOException{Channel ch=requireChannel(channel);if(!ch.active())throw new IllegalStateException("Channel is inactive");RoomType rt=requireRoom(roomType);if(bookings.stream().anyMatch(b->b.channel().equals(ch.id())&&b.externalReference().equalsIgnoreCase(reference)))throw new IllegalStateException("Duplicate external booking reference");if(!out.isAfter(in)||rooms<1)throw new IllegalArgumentException("Invalid stay or room count");BigDecimal rate=quotedRate==null?null:quotedRate;if(rate==null){Rate r=rateFor(rt.code(),ch.id(),in);if(r==null)throw new IllegalStateException("No channel rate configured for check-in date");rate=r.nightlyRate();}if(rate.signum()<=0)throw new IllegalArgumentException("Rate must be positive");for(LocalDate d=in;d.isBefore(out);d=d.plusDays(1)){if(available(rt.code(),ch.id(),d)<rooms)throw new IllegalStateException("No availability for "+d+" on channel "+ch.id());}ExternalBooking b=new ExternalBooking(nextId++,ch.id(),reference,guest,rt.code(),in,out,rooms,rate,BookingStatus.CONFIRMED,LocalDateTime.now(clock));bookings.add(b);try{persist();}catch(IOException e){bookings.remove(b);nextId--;throw e;}return b;}
    public synchronized void updateStatus(long id,BookingStatus status)throws IOException{int i=index(id);ExternalBooking b=bookings.get(i);if(b.status()==BookingStatus.CANCELLED&&status!=BookingStatus.CANCELLED)throw new IllegalStateException("Cancelled booking cannot be reactivated; import it again");ExternalBooking n=new ExternalBooking(b.id(),b.channel(),b.externalReference(),b.guestName(),b.roomType(),b.checkIn(),b.checkOut(),b.rooms(),b.nightlyRate(),status,b.importedAt());bookings.set(i,n);try{persist();}catch(IOException e){bookings.set(i,b);throw e;}}
    public synchronized BigDecimal grossRevenue(){return bookings.stream().filter(b->b.status()!=BookingStatus.CANCELLED).map(ExternalBooking::gross).reduce(BigDecimal.ZERO,BigDecimal::add);}
    public synchronized BigDecimal commission(){return bookings.stream().filter(b->b.status()!=BookingStatus.CANCELLED).map(b->b.gross().multiply(requireChannel(b.channel()).commissionPercent()).divide(new BigDecimal("100"),2,RoundingMode.HALF_UP)).reduce(BigDecimal.ZERO,BigDecimal::add);}
    public synchronized BigDecimal netRevenue(){return grossRevenue().subtract(commission());}
    public synchronized String csv(){StringBuilder s=new StringBuilder("ID,Channel,External reference,Guest,Room type,Check-in,Check-out,Rooms,Nights,Nightly rate,Gross,Commission,Net,Status\n");for(ExternalBooking b:bookings()){BigDecimal c=b.gross().multiply(requireChannel(b.channel()).commissionPercent()).divide(new BigDecimal("100"),2,RoundingMode.HALF_UP);s.append(b.id()).append(',').append(q(b.channel())).append(',').append(q(b.externalReference())).append(',').append(q(b.guestName())).append(',').append(q(b.roomType())).append(',').append(b.checkIn()).append(',').append(b.checkOut()).append(',').append(b.rooms()).append(',').append(b.nights()).append(',').append(b.nightlyRate()).append(',').append(b.gross()).append(',').append(c).append(',').append(b.gross().subtract(c)).append(',').append(b.status()).append('\n');}return s.toString();}
    private static String q(String s){return "\""+s.replace("\"","\"\"")+"\"";}private Rate rateFor(String rt,String ch,LocalDate d){return rates.stream().filter(r->r.roomType().equals(rt)&&r.channel().equals(ch)&&!d.isBefore(r.from())&&!d.isAfter(r.to())).max(Comparator.comparing(Rate::from)).orElse(null);}private Channel requireChannel(String id){Channel c=channels.get(req(id).toUpperCase(Locale.ROOT));if(c==null)throw new IllegalArgumentException("Unknown channel: "+id);return c;}private RoomType requireRoom(String id){RoomType r=roomTypes.get(req(id).toUpperCase(Locale.ROOT));if(r==null)throw new IllegalArgumentException("Unknown room type: "+id);return r;}private int index(long id){for(int i=0;i<bookings.size();i++)if(bookings.get(i).id()==id)return i;throw new IllegalArgumentException("Unknown booking id");}
    private void persist()throws IOException{Path tmp=Files.createTempFile(file.toAbsolutePath().getParent(),"channels-",".tmp");try{List<String> rows=new ArrayList<>();for(Channel c:channels.values())rows.add(String.join("\t","C",enc(c.id()),enc(c.name()),c.commissionPercent().toPlainString(),Boolean.toString(c.active())));for(RoomType r:roomTypes.values())rows.add(String.join("\t","T",enc(r.code()),enc(r.name()),Integer.toString(r.physicalRooms())));for(Rate r:rates)rows.add(String.join("\t","R",enc(r.roomType()),enc(r.channel()),r.from().toString(),r.to().toString(),r.nightlyRate().toPlainString(),Integer.toString(r.allotment())));for(ExternalBooking b:bookings)rows.add(String.join("\t","B",Long.toString(b.id()),enc(b.channel()),enc(b.externalReference()),enc(b.guestName()),enc(b.roomType()),b.checkIn().toString(),b.checkOut().toString(),Integer.toString(b.rooms()),b.nightlyRate().toPlainString(),b.status().name(),b.importedAt().toString()));Files.write(tmp,rows,StandardCharsets.UTF_8);try{Files.move(tmp,file,StandardCopyOption.ATOMIC_MOVE,StandardCopyOption.REPLACE_EXISTING);}catch(AtomicMoveNotSupportedException e){Files.move(tmp,file,StandardCopyOption.REPLACE_EXISTING);}}finally{Files.deleteIfExists(tmp);}}
    private void load()throws IOException{for(String line:Files.readAllLines(file,StandardCharsets.UTF_8)){String[] f=line.split("\t",-1);try{switch(f[0]){case "C"->{if(f.length==5){Channel c=new Channel(dec(f[1]),dec(f[2]),new BigDecimal(f[3]),Boolean.parseBoolean(f[4]));channels.put(c.id(),c);}}case "T"->{if(f.length==4){RoomType r=new RoomType(dec(f[1]),dec(f[2]),Integer.parseInt(f[3]));roomTypes.put(r.code(),r);}}case "R"->{if(f.length==7)rates.add(new Rate(dec(f[1]),dec(f[2]),LocalDate.parse(f[3]),LocalDate.parse(f[4]),new BigDecimal(f[5]),Integer.parseInt(f[6])));}case "B"->{if(f.length==12){ExternalBooking b=new ExternalBooking(Long.parseLong(f[1]),dec(f[2]),dec(f[3]),dec(f[4]),dec(f[5]),LocalDate.parse(f[6]),LocalDate.parse(f[7]),Integer.parseInt(f[8]),new BigDecimal(f[9]),BookingStatus.valueOf(f[10]),LocalDateTime.parse(f[11]));bookings.add(b);nextId=Math.max(nextId,b.id()+1);}}}}catch(RuntimeException ignored){}}}
}
